Trading from within Kolonnade Shopping Centre gives the restaurant the convenience of mall parking and nearby shopping for families combining a meal with other errands. It is open daily from 8am to 10pm. Based in Montana, Pretoria, Panarottis Montana suits families and groups looking for a casual, reliable Italian meal with a children''s option on the menu.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.eatout.co.za/?p=103635', '$[#]', 'https://au.trip.com/restaurant/south%20africa/pretoria/detail/Panarottis%20Montana-19861152'), description_enriched_at = datetime('now') WHERE slug = 'panarottis-montana-montana' AND description = 'Panarottis Montana is a branch of the family-style Italian restaurant chain inside Kolonnade Shopping Centre, serving pizzas, pastas and a dedicated kids'' menu, open daily from 8am to 10pm, in Montana, Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
